#include <string>
#include <algorithm>

class Solution {
public:
    int maxPower(std::string s) {
        int maxP = 1, cur = 1;
        for (int i = 1; i < (int)s.size(); ++i) {
            if (s[i] == s[i - 1]) {
                cur++;
                maxP = std::max(maxP, cur);
            } else {
                cur = 1;
            }
        }
        return maxP;
    }
};

class Solution {
    public int maxPower(String s) {
        int maxP = 1, cur = 1;
        for (int i = 1; i < s.length(); i++) {
            if (s.charAt(i) == s.charAt(i - 1)) {
                cur++;
                maxP = Math.max(maxP, cur);
            } else {
                cur = 1;
            }
        }
        return maxP;
    }
}

var maxPower = function(s) {
    let maxP = 1, cur = 1;
    for (let i = 1; i < s.length; i++) {
        if (s[i] === s[i - 1]) {
            cur++;
            if (cur > maxP) maxP = cur;
        } else {
            cur = 1;
        }
    }
    return maxP;
};
